import{_ as a,o as t,c as n,j as r}from"./chunks/framework.DsyGq6Zh.js";const h=JSON.parse('{"title":"Human Attention as an Engineering Constraint","description":"Kanban, review queueing, cost of errors, and dynamic human–AI resource allocation.","frontmatter":{"title":"Human Attention as an Engineering Constraint","description":"Kanban, review queueing, cost of errors, and dynamic human–AI resource allocation."},"headers":[],"relativePath":"research/systems/human-attention-kanban.md","filePath":"research/systems/human-attention-kanban.md"}'),o={name:"research/systems/human-attention-kanban.md"};function i(s,e,l,c,u,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="human-attention-as-an-engineering-constraint" tabindex="-1">Human Attention as an Engineering Constraint <a class="header-anchor" href="#human-attention-as-an-engineering-constraint" aria-label="Permalink to &quot;Human Attention as an Engineering Constraint&quot;">​</a></h1><p><em>Research and economic hypothesis · November 2026</em></p><p>As AI agents make generation inexpensive, <strong>the scarcest resource may be the attention of people qualified to verify and authorize their output</strong>.</p><p>Optimizing for more AI-produced code, claims, or multimedia can worsen the real bottleneck: an ever-growing queue of decisions humans must inspect.</p><p>I want to evaluate systems by accepted, reliable value per human-review minute—not by generated tokens per second.</p><h2 id="kanban-as-flow-control" tabindex="-1">Kanban as flow control <a class="header-anchor" href="#kanban-as-flow-control" aria-label="Permalink to &quot;Kanban as flow control&quot;">​</a></h2><p>Kanban&#39;s work-in-progress limits, explicit policies, and pull-based flow provide a useful model. Yet the architecture needs two different flows:</p><ul><li><strong>Knowledge flow:</strong> source ingestion, sensor observations, candidate claims, verification, graph promotion, and artifact generation.</li><li><strong>Decision flow:</strong> ambiguous cases, policy changes, consequential actions, and reviewer approvals.</li></ul><p>Billions of emails should not become billions of visible board cards. The operational board represents batches, blocked jobs, reviewer cases, decisions, and capacity; the detailed event and provenance records remain in the underlying system.</p><p>When Pit Stops exceed review capacity, the scheduler should apply backpressure, group repetitive decisions, gather cheaper additional evidence, and prioritize cases by risk and expected value. It must never bypass a mandatory authority gate merely to clear the queue.</p><h2 id="value-of-additional-review" tabindex="-1">Value of additional review <a class="header-anchor" href="#value-of-additional-review" aria-label="Permalink to &quot;Value of additional review&quot;">​</a></h2><p>A useful starting model is:</p><p><strong>Total expected cost = compute + expert review + error consequences + recovery.</strong></p><p>The optimal pathway may be deterministic code; a small local model; a frontier model; an authorized delegate; or a human. A cheap inference that produces substantial rework may be economically worse than an expensive evaluation that prevents a serious error.</p><p>Case-by-case approvals can also create higher-value policy proposals. An operator might spend two minutes correcting one ambiguous name, or the same time authorizing a tested, narrow entity-resolution rule that applies to thousands of future observations.</p><p>The policy must still be monitored on held-out examples and sampled automatic decisions.</p><h2 id="what-to-measure" tabindex="-1">What to measure <a class="header-anchor" href="#what-to-measure" aria-label="Permalink to &quot;What to measure&quot;">​</a></h2><ul><li><strong>Review minutes per qualified claim or accepted artifact</strong></li><li><strong>Consequence-weighted false promotions and escaped errors</strong></li><li><strong>Queue time, flow time, throughput, and rework</strong></li><li><strong>Provenance completeness and contradiction-retrieval success</strong></li><li><strong>Inference, storage, and recovery costs</strong></li><li><strong>Reviewer cognitive load and quality of decisions under interruption</strong></li></ul><p>Throughput alone is a poor outcome measure: if the system promotes incorrect knowledge faster, it has not improved.</p><h2 id="scientific-questions" tabindex="-1">Scientific questions <a class="header-anchor" href="#scientific-questions" aria-label="Permalink to &quot;Scientific questions&quot;">​</a></h2><p>Does value-aware scheduling outperform FIFO or fixed-confidence review when reviewer capacity is limited? Can progressive commissioning reduce the number of low-value human interruptions without increasing errors? Can progressive-disclosure review interfaces help experts understand and resolve cases more accurately?</p><p>Earlier work matters here. <a href="https://www.microsoft.com/en-us/research/people/horvitz/publications/" target="_blank" rel="noreferrer">Horvitz et al. (1999)</a> studied attention-sensitive alerting. <a href="https://digitalcommons.njit.edu/fac_pubs/6913/" target="_blank" rel="noreferrer">Grandhi and Jones (2015)</a> investigated the role of interruption context. <a href="https://digitalcommons.njit.edu/fac_pubs/14771/" target="_blank" rel="noreferrer">Sylla and Wen (2002)</a> combined decision criteria and goal programming for technology evaluation. <a href="https://aclanthology.org/2026.akbc-1.16/" target="_blank" rel="noreferrer">GRACE (2026)</a> expressly optimizes return on expert attention.</p><p>The research claim must therefore involve a <strong>specific new mechanism and measured benefit</strong>, not simply recognizing that review time is scarce.</p><p><a href="./">Research series</a> · <a href="./dissertation-proposal">Dissertation proposal</a></p>',24)])])}const m=a(o,[["render",i]]);export{h as __pageData,m as default};
